SELECT 'M191-LISTE_UNGEKLAERT-SUTTONS-alt' AS fall,
       COUNT(*)                          AS laeufe,
       MAX(CASE WHEN rn = 1 THEN ms END) AS profil_aufwaermlauf,
       MIN(CASE WHEN rn > 1 THEN ms END) AS profil_beste_von_fuenf,
       GROUP_CONCAT(CASE WHEN rn > 1 THEN ms END ORDER BY rn) AS profil_alle_fuenf,
       ROUND(@w1 / 1000, 3)              AS wand_aufwaermlauf,
       ROUND(LEAST(@w2, @w3, @w4, @w5, @w6) / 1000, 3) AS wand_beste_von_fuenf,
       CONCAT_WS('/', ROUND(@w2 / 1000, 3), ROUND(@w3 / 1000, 3), ROUND(@w4 / 1000, 3), ROUND(@w5 / 1000, 3), ROUND(@w6 / 1000, 3))       AS wand_alle_fuenf
FROM (SELECT ROW_NUMBER() OVER (ORDER BY QUERY_ID) AS rn,
             ROUND(SUM(DURATION) * 1000, 3) AS ms
      FROM information_schema.PROFILING
      WHERE QUERY_ID > @basis + 1 AND QUERY_ID <= @basis + 19
        AND (QUERY_ID - @basis) % 3 = 0
      GROUP BY QUERY_ID) t;

SELECT '=== M191-VERENGUNG_UNGEKLAERT-NEXANS-alt · Plan (Regel L15) ===' AS marke;
EXPLAIN select sum(`kumuliert`.`anzahl`), max(case when `kumuliert`.`kumuliert` >= 51 then `kumuliert`.`stunde` end) from (select `je_stunde`.`stunde`, `je_stunde`.`anzahl`, sum(case when `je_stunde`.`voll` then `je_stunde`.`anzahl` else 0 end) over (order by `je_stunde`.`stunde` desc) as `kumuliert` from (select `overlord_monitor`.`message_rollup`.`stunde` as `stunde`, sum(`overlord_monitor`.`message_rollup`.`anzahl`) as `anzahl`, (`overlord_monitor`.`message_rollup`.`stunde` >= timestamp '2025-11-30 05:00:00.0' and `overlord_monitor`.`message_rollup`.`stunde` <= timestamp '2025-12-30 03:00:00.0') as `voll` from `overlord_monitor`.`message_rollup` where (`overlord_monitor`.`message_rollup`.`stunde` >= timestamp '2025-11-30 04:00:00.0' and `overlord_monitor`.`message_rollup`.`stunde` <= timestamp '2025-12-30 04:00:00.0' and `overlord_monitor`.`message_rollup`.`stunde` < timestamp '2026-08-27 15:00:00.0' and exists (select 1 as `one` from `GlassfishDB`.`Process` as `verengung_process` join `GlassfishDB`.`ProjectMandant` on `GlassfishDB`.`ProjectMandant`.`ProjectID` = `verengung_process`.`ProjectID` where (`verengung_process`.`ProcessID` = `overlord_monitor`.`message_rollup`.`process_id` and `GlassfishDB`.`ProjectMandant`.`MandantID` = 'NEXANS')) and (`overlord_monitor`.`message_rollup`.`message_status` is null or (not (`overlord_monitor`.`message_rollup`.`message_status` like 'ERROR\\_%' escape '\\' or `overlord_monitor`.`message_rollup`.`message_status` = 'COMMIT_REJECTED') and `overlord_monitor`.`message_rollup`.`message_status` not in ('COMMIT_RECEIVED', 'EERP_RECEIVED', 'FINISHED', 'MERGED', 'RUNNING', 'SPLITTED', 'SUSPENDED')))) group by `overlord_monitor`.`message_rollup`.`stunde`) as `je_stunde`) as `kumuliert`;

