select sum(`kumuliert`.`anzahl`), max(case when `kumuliert`.`kumuliert` >= 51 then `kumuliert`.`stunde` end) from (select `je_stunde`.`stunde`, `je_stunde`.`anzahl`, sum(case when `je_stunde`.`voll` then `je_stunde`.`anzahl` else 0 end) over (order by `je_stunde`.`stunde` desc) as `kumuliert` from (select `overlord_monitor`.`message_rollup`.`stunde` as `stunde`, sum(`overlord_monitor`.`message_rollup`.`anzahl`) as `anzahl`, (`overlord_monitor`.`message_rollup`.`stunde` >= timestamp '2025-11-30 05:00:00.0' and `overlord_monitor`.`message_rollup`.`stunde` <= timestamp '2025-12-30 03:00:00.0') as `voll` from `overlord_monitor`.`message_rollup` where (`overlord_monitor`.`message_rollup`.`stunde` >= timestamp '2025-11-30 04:00:00.0' and `overlord_monitor`.`message_rollup`.`stunde` <= timestamp '2025-12-30 04:00:00.0' and `overlord_monitor`.`message_rollup`.`stunde` < timestamp '2026-08-27 15:00:00.0' and exists (select 1 as `one` from `GlassfishDB`.`Process` as `verengung_process` join `GlassfishDB`.`ProjectMandant` on `GlassfishDB`.`ProjectMandant`.`ProjectID` = `verengung_process`.`ProjectID` where (`verengung_process`.`ProcessID` = `overlord_monitor`.`message_rollup`.`process_id` and `GlassfishDB`.`ProjectMandant`.`MandantID` = 'SUTTONS')) and (`overlord_monitor`.`message_rollup`.`message_status` is null or (not (`overlord_monitor`.`message_rollup`.`message_status` like 'ERROR\\_%' escape '\\' or `overlord_monitor`.`message_rollup`.`message_status` = 'COMMIT_REJECTED') and `overlord_monitor`.`message_rollup`.`message_status` not in ('COMMIT_RECEIVED', 'EERP_RECEIVED', 'FINISHED', 'MERGED', 'RUNNING', 'SPLITTED', 'SUSPENDED')))) group by `overlord_monitor`.`message_rollup`.`stunde`) as `je_stunde`) as `kumuliert`;
